create or replace function pg_temp.probe_affected_rows(p_sql text) returns integer language plpgsql as $f$
declare v_count integer;
begin
  execute p_sql;
  get diagnostics v_count = row_count;
  return v_count;
exception when others then
  return -1;
end;
$f$;

